-- search_articles after #17: cxp_core::knowledge::SEARCH_ARTICLES_SQL with
-- pgbench variables for its binds (regenerate if that SQL changes).
BEGIN;
SET LOCAL ROLE otto_app;
SELECT set_config('app.org_id', :org, true);
SET LOCAL jit = off;
WITH lexemes AS ( SELECT DISTINCT 'l' || l AS term FROM unnest(tsvector_to_array(to_tsvector('english', :q))) AS l ), windows AS ( SELECT DISTINCT 's' || g AS term FROM search_windows(lower(:q)) AS g ), ranked AS ( SELECT term, row_number() OVER (ORDER BY n, term) AS rk FROM ( SELECT w.term, (SELECT count(*) FROM (SELECT 1 FROM knowledge_search_terms t WHERE t.org_id = :org::uuid AND t.term = w.term LIMIT 256) AS p) AS n FROM windows AS w) AS c ), fts_hits AS ( SELECT t.article_id FROM knowledge_search_terms t WHERE t.org_id = :org::uuid AND t.term = ANY (ARRAY(SELECT term FROM lexemes)) GROUP BY t.article_id HAVING count(*) = (SELECT count(*) FROM lexemes) ), title_hits AS ( SELECT t.article_id FROM knowledge_search_terms t WHERE t.org_id = :org::uuid AND t.term = (SELECT term FROM ranked WHERE rk = 1) AND NOT EXISTS (SELECT 1 FROM ranked r WHERE r.rk IN (2, 3) AND NOT EXISTS (SELECT 1 FROM knowledge_search_terms t2 WHERE t2.org_id = :org::uuid AND t2.term = r.term AND t2.article_id = t.article_id)) UNION SELECT t.article_id FROM knowledge_search_terms t WHERE length(lower(:q)) < 4 AND t.org_id = :org::uuid AND t.term >= 's' || lower(:q) AND t.term <= 's' || lower(:q) || U&'\+10FFFF\+10FFFF\+10FFFF' ) SELECT id, title, content, category, tags, metadata, published, created_at, updated_at FROM knowledge_articles WHERE org_id = :org::uuid AND published = true AND id = ANY (ARRAY(SELECT article_id FROM fts_hits UNION SELECT article_id FROM title_hits)) AND (search_tsv @@ plainto_tsquery('english', :q) OR title ILIKE :pat) ORDER BY ts_rank(search_tsv, plainto_tsquery('english', :q)) DESC, created_at DESC, id LIMIT 20;
COMMIT;
